580	      kind: "digest-email",
581	      runAt: toIsoTimestamp(new Date()),
582	      attempts: 0,
583	      payload: {
584	        orgId: payload.orgId,
585	        recipientId: payload.recipientId,
586	        windowStart: payload.windowStart,
587	      },
588	    });
589	  });
590	}
