279	/**
280	 * Runs a query against the denormalised index. Field-scoped syntax
281	 * (`status:done`) is an `advanced_search` feature, so a query containing a
282	 * colon is rejected for plans that do not include it rather than silently
283	 * being treated as literal text.
284	 */
285	export async function search(
286	  actor: Actor,
287	  input: SearchQueryInput,
288	): Promise<Page<SearchHit>> {
289	  assertOrgScope(actor, input.orgId);
290	  assertCan(actor, "issue:read", orgResource(input.orgId));
291	
292	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
293	  if (!verdict.allowed) {
294	    throw new Error(
295	      `Search rate limit reached; try again after ${verdict.resetAt}`,
296	    );
297	  }
298	
299	  const org = await orgRepo.findOrgById(input.orgId);
300	  const advanced = isEnabled("advanced_search", {
301	    orgId: input.orgId,
302	    userId: actor.userId,
303	    plan: org?.plan ?? "free",
304	    role: actor.role,
305	    overrides: org?.settings.enabledFlagOverrides,
306	  });
307	
308	  if (input.q.includes(":") && !advanced) {
309	    throw new Error("Field-scoped search is not included in this plan");
310	  }
311	
312	  const page = await searchRepo.searchDocuments(input);
313	
314	  return {
315	    items: page.items.map((row) => ({
316	      kind: row.subjectKind,
317	      id: row.subjectId,
318	      title: row.content.split("\n")[0] ?? row.subjectId,
319	      snippet: snippetAround(row.content, input.q),
320	      href: hrefFor(row.subjectKind, row.subjectId),
321	    })),
322	    nextCursor: page.nextCursor,
323	    total: page.total,
324	  };
325	}
