371	/**
372	 * Keeps the index in step with writes. Every handler re-reads the row rather
373	 * than trusting the event payload, so a partially-applied write can never be
374	 * indexed as if it had succeeded.
375	 */
376	export function registerSearchListeners(): Unsubscribe {
377	  const offs: Unsubscribe[] = [
378	    subscribe("issue.created", async (payload) => {
379	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
380	      if (issue) await indexIssue(payload.orgId, issue);
381	    }),
382	    subscribe("issue.updated", async (payload) => {
383	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
384	      if (issue) await indexIssue(payload.orgId, issue);
385	    }),
386	    subscribe("issue.archived", async (payload) => {
387	      await removeFromIndex(payload.orgId, "issue", payload.issueId);
388	    }),
389	    subscribe("comment.created", async (payload) => {
390	      const comment = await commentRepo.findCommentById(
