392	        payload.commentId,
393	      );
394	      if (comment) await indexComment(payload.orgId, comment);
395	    }),
396	    subscribe("comment.deleted", async (payload) => {
397	      await removeFromIndex(payload.orgId, "comment", payload.commentId);
398	    }),
399	    subscribe("project.created", async (payload) => {
400	      const project = await projectRepo.findProjectById(
