424	function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
425	  switch (kind) {
426	    case "issue":
427	      return `/issues/${subjectId}`;
428	    case "comment":
429	      return `/comments/${subjectId}`;
430	    case "project":
431	      return `/projects/${subjectId}`;
432	  }
433	}
