638	import type {
639	  Notification,
640	  NotificationChannel,
641	  NotificationKind,
642	  NotificationPreference,
643	} from "@/types/notification";
644	
645	export type NotificationPayload = {
646	  title: string;
647	  body: string;
648	  href: string;
649	  actorId: UserId | null;
650	};
651	
652	/** Channels used when a recipient has never touched their preferences. */
653	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
654	
655	/**
656	 * Writes one notification row per recipient, each with the channel set that
657	 * recipient's preferences allow. A recipient who has muted every channel is
658	 * skipped entirely rather than given a row nobody will ever see.
659	 */
660	export async function notify(
661	  orgId: OrgId,
662	  kind: NotificationKind,
663	  recipients: readonly UserId[],
664	  payload: NotificationPayload,
665	): Promise<readonly Notification[]> {
666	  if (recipients.length === 0) return [];
667	
668	  const org = await orgRepo.findOrgById(orgId);
669	  const flags: FlagContext = {
670	    orgId,
671	    userId: payload.actorId,
672	    plan: org?.plan ?? "free",
673	    role: null,
674	    overrides: org?.settings.enabledFlagOverrides,
675	  };
676	
677	  const rows = [];
678	
679	  for (const recipientId of new Set(recipients)) {
680	    if (recipientId === payload.actorId) continue;
681	
682	    const preference = await preferenceRepo.getPreference(
683	      orgId,
684	      recipientId,
685	      kind,
686	    );
687	    const channels = resolveChannels(preference, flags);
688	    if (channels.length === 0) continue;
689	
690	    rows.push({
691	      orgId,
692	      recipientId,
693	      kind,
694	      title: payload.title,
695	      body: payload.body,
696	      href: payload.href,
697	      actorId: payload.actorId,
698	      channels,
699	    });
700	  }
701	
702	  return notificationRepo.insertNotifications(orgId, rows);
703	}
