/** Fetches issues by id, archived ones included, in the order of `issueIds`. */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();

  const labelsByIssue = await listLabelsForIssues(orgId, issueIds);
  const byId = new Map(rows.map((row) => [row.id, row]));

  return issueIds.flatMap((id) => {
    const row = byId.get(id);
    if (!row) return [];
    return [toIssue(row, (labelsByIssue[id] ?? []).map((label) => label.id))];
  });
}

/** A stored bulk import: which project it went to and what it created. */
export type IssueImportRecord = {
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
