const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Bulk import: every row becomes an issue, in file order, or nothing does.
 * Gates run in the same order as `createIssue`, then the replay check, the
 * per-project quota for the whole batch and the rate allowance (one unit per
 * row) — all before the single transaction that writes the batch. One
 * `issues.imported` event announces it; no per-issue `issue.created`.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const previous = await issueRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (previous !== null) {
    if (previous.projectId !== project.id) {
      // The key was first used for another project: its issues are only
      // handed back to someone who could have imported there too.
      const original = requireFound(
        await projectRepo.findProjectById(input.orgId, previous.projectId),
        "Project",
        previous.projectId,
      );
      assertCan(actor, "issue:create", projectResource(original));
    }
    return {
      importKey: previous.importKey,
      projectId: previous.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, previous.issueIds),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (
    input.rows.length === 0 ||
    wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)
  ) {
    throw new Error(
      input.rows.length === 0
        ? "An import needs at least one row"
        : `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const memberByEmail = await memberRepo.mapActiveMemberEmails(input.orgId);

  const issues = await issueRepo.insertImportedIssues({
    orgId: input.orgId,
    projectId: project.id,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (memberByEmail.get(row.assigneeEmail.trim().toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: row.labels,
    })),
  });

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues,
    replayed: false,
  };
}

