/** Fetches issues by id, archived ones included, in the order of `issueIds`. */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();

  const labelsByIssue = await listLabelsForIssues(orgId, issueIds);
  const byId = new Map(rows.map((row) => [row.id, row]));

  return issueIds.flatMap((id) => {
    const row = byId.get(id);
    if (!row) return [];
    return [toIssue(row, (labelsByIssue[id] ?? []).map((label) => label.id))];
  });
}

/** A stored bulk import: which project it went to and what it created. */
export type IssueImportRecord = {
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    importKey: row.importKey,
    projectId: row.projectId as ProjectId,
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

/** One import row with its assignee already resolved to a member. */
export type ImportedIssueDraft = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
};

/**
 * Writes a whole import in one transaction: missing labels, the issues
 * (numbered in file order after the project's highest number), their label
 * links and the import record. Either all of it lands or none of it does.
 */
export async function insertImportedIssues(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  rows: readonly ImportedIssueDraft[];
}): Promise<readonly Issue[]> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const labelIdByName = new Map<string, LabelId>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, input.orgId))
        .all()
        .map((row) => [row.name, row.id as LabelId]),
    );

    for (const row of input.rows) {
      for (const name of row.labelNames) {
        if (labelIdByName.has(name)) continue;
        const id = newId() as LabelId;
        tx.insert(labels)
          .values({
            id,
            orgId: input.orgId,
            name,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, id);
      }
    }

    const max = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = max?.value ?? 0;

    const created: Issue[] = [];

    for (const row of input.rows) {
      number += 1;
      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = [...new Set(row.labelNames)].map(
        (name) => labelIdByName.get(name) as LabelId,
      );
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }

      created.push(toIssue(inserted, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        importedBy: input.authorId,
        createdAt: stamp,
      })
      .run();

    return created;
  });
}
''')

