import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { getDb } from "@/server/db";
import * as issueService from "@/server/services/issue-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as usageRepo from "@/server/repositories/usage-repository";
import { importIssuesSchema } from "@/schemas/issue-import";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("imports", async () => {
  registerEventHandlers();
  const t = await createTenant("smoke");
  const other = await createTenant("other");
  const db = getDb().$client;
  const adminEmail = (db.prepare("select email from users where id=?").get(t.userIds.admin) as any).email;
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  const created: unknown[] = []; const imported: any[] = [];
  subscribe("issue.created", (p) => { created.push(p); });
  subscribe("issues.imported", (p) => { imported.push(p); });
  const input = importIssuesSchema.parse({
    orgId: t.org.id, projectId: t.project.id, importKey: "key-12345",
    rows: [
      { title: "First row", assigneeEmail: adminEmail.toUpperCase(), labels: ["bug", "bug", "Bug"] },
      { title: "Second row", labels: ["bug"], assigneeEmail: "nobody@example.com", status: "done" },
    ],
  });
  const r = await issueService.importIssues(t.actors.member, input);
  expect(r.replayed).toBe(false);
  expect(r.issues.map((i) => i.number)).toEqual([2, 3]);
  expect(r.issues[0]!.assigneeId).toBe(t.userIds.admin);
  expect(r.issues[1]!.assigneeId).toBeNull();
  expect(r.issues[0]!.labelIds).toHaveLength(2);
  expect(created).toHaveLength(0);
  expect(imported).toHaveLength(1);
  expect((db.prepare("select count(*) c from labels").get() as any).c).toBe(2);
  expect((db.prepare("select count(*) c from search_index where subject_kind='issue'").get() as any).c).toBe(3);
  expect(db.prepare("select action, subject_kind, metadata from activity_events where action='issues.imported'").all()).toEqual([
    { action: "issues.imported", subject_kind: "project", metadata: JSON.stringify({ count: 2, importKey: "key-12345" }) },
  ]);
  expect((db.prepare("select count(*) c from notifications").get() as any).c).toBe(0);
  const cached = await usageRepo.getUsage(t.org.id);
  expect(cached.issuesUsed).toBe((await usageRepo.recomputeUsage(t.org.id)).issuesUsed);
  const again = await issueService.importIssues(t.actors.member, { ...input, rows: [input.rows[0]!] });
  expect(again.replayed).toBe(true);
  expect(again.issues).toEqual(r.issues);
  expect(imported).toHaveLength(1);
  await expect(issueService.importIssues(t.actors.viewer, { ...input, importKey: "another-key" })).rejects.toThrow();
  await expect(issueService.importIssues(t.actors.member, { ...input, projectId: other.project.id, importKey: "another-key" })).rejects.toThrow(/not found/);
  const next = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  expect(next.number).toBe(4);
});
